import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Doctor } from './doctor.entity';
import { Person } from 'src/person/person.entity';
import { CreateDoctorDto } from './dto/create-doctor.dto';
import { UpdateDoctorDto } from './dto/update-doctor.dto';
import { Specialty } from 'src/specialty/specialty.entity';

@Injectable()
export class DoctorService {
    constructor(
        @InjectRepository(Doctor) private readonly doctorRepository: Repository<Doctor>,
        @InjectRepository(Person) private readonly personRepository: Repository<Person>,
        @InjectRepository(Specialty) private readonly specialtyRepository: Repository<Specialty>,
) {}

    // Create a doctor with the correct relations
    async create (dto:CreateDoctorDto) {
        // Search for person
        const person = await this.personRepository.findOneBy({id: dto.personaId});
        if (!person) {
            throw new Error('Person not found');
        }
        // Search for specialty
        const specialty = await this.specialtyRepository.findOneBy({id_especialidad: dto.specialtyId});
        if (!specialty) {
            throw new Error('Specialty not found');
        }
        // Create doctor
        const doctor = this.doctorRepository.create({person, specialty, licenseNumber: dto.licenseNumber});
        return this.doctorRepository.save(doctor);
    }

    // Find all doctors with relations person
    findAll() {
        return this.doctorRepository.find({relations: ['person']});
    }

    // Find one doctor with relations person
    findOne(id: number) {
        return this.doctorRepository.findOne({where: {id}, relations: ['person']});
    }

    // Update doctor with correct relations
    async update(id: number, dto: UpdateDoctorDto) {
        // Verification of existence of doctor
        const doctor = await this.doctorRepository.findOne({
            where: { id },
            relations: ['person', 'specialty'],
        });

        // If Doctor not found
        if (!doctor) {
            throw new Error('Doctor not found');
        }

        // If send new personId, update relation
        if (dto.personaId) {
            const person = await this.personRepository.findOneBy({ id: dto.personaId });
            if (!person) throw new Error('Person not found');
            doctor.person = person;
        }

        // If send new specialtyId, update relation
        if (dto.specialtyId) {
            const specialty = await this.specialtyRepository.findOneBy({
            id_especialidad: dto.specialtyId,
            });
            if (!specialty) throw new Error('Specialty not found');
            doctor.specialty = specialty;
        }

        // Update simple fields
        if (dto.licenseNumber) {
            doctor.licenseNumber = dto.licenseNumber;
        }

        // Save changes
        return this.doctorRepository.save(doctor);
    }

    // Delete doctor by id
    remove(id: number) {
        return this.doctorRepository.delete(id);    
    }    

}

import { Injectable } from '@nestjs/common';
import { CreateInvoiceDto } from './dto/create-invoice.dto';
import { UpdateInvoiceDto } from './dto/update-invoice.dto';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Invoice } from './invoice.entity';
import { Appointment } from 'src/appointment/appointment.entity';
import { Patient } from 'src/patient/patient.entity';

@Injectable()
export class InvoiceService {
  constructor(
    @InjectRepository(Invoice)
    private readonly invoiceRepository: Repository<Invoice>,
    @InjectRepository(Appointment)
    private readonly appointmentRepository: Repository<Appointment>,
    @InjectRepository(Patient)
    private readonly patientRepository: Repository<Patient>,
  ) {}

  // Create an invoice with the correct relations
  async create(dto: CreateInvoiceDto) {
    // Search for appointment
  const appointment = await this.appointmentRepository.findOne({
    where: { id: dto.id_cita },
  });
  if (!appointment) throw new Error('Appointment not found');
  // Search for patient
  const patient = await this.patientRepository.findOne({
    where: { id: dto.id_paciente },
  });
  if (!patient) throw new Error('Patient not found');

  // Crear la factura con las relaciones correctas
  const invoice = this.invoiceRepository.create({
    total: dto.total,
    metodo_pago: dto.metodo_pago,
    estado_pago: dto.estado_pago || 'Pendiente',
    propety_cita: appointment,
    propety_patient: patient,
  });

  return this.invoiceRepository.save(invoice);
}


  // Find all invoices with relations appointment and patient
  findAll() {
    return this.invoiceRepository.find({
      relations: ['propety_cita', 'propety_patient'],
    });
  }

  // Find one invoice with relations appointment and patient
  async findOne(id: number) {
    const invoice = await this.invoiceRepository.findOne({
      where: { id_factura: id },
      relations: ['propety_cita', 'propety_patient'],
    });
    if (!invoice) throw new Error('Invoice not found');
    return invoice;
  }

  // Update invoice with correct relations
  async update(id: number, dto: UpdateInvoiceDto) {
    // Verification of existence of invoice
    const invoice = await this.findOne(id);

    // If send new appointmentId, update relation
    if (dto.id_cita) {
      const appointment = await this.appointmentRepository.findOne({
        where: { id: dto.id_cita },
      });
      if (!appointment) throw new Error('Appointment not found');
      invoice.propety_cita = appointment;
    }

    // If send new patientId, update relation
    if (dto.id_paciente) {
      const patient = await this.patientRepository.findOne({
        where: { id: dto.id_paciente },
      });
      if (!patient) throw new Error('Patient not found');
      invoice.propety_patient = patient;
    }

    // Update simple fields
    Object.assign(invoice, dto);
    return this.invoiceRepository.save(invoice);
  }

  // Delete invoice by id
  async remove(id: number) {
    const invoice = await this.findOne(id);
    await this.invoiceRepository.remove(invoice);
    return { message: `Invoice with id ${id} deleted successfully` };
  }
}

